import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.CWWEQfK7.js";const m=JSON.parse('{"title":"Ershu","description":"Self-hosted project context for private enterprise code, turning multiple repositories into searchable, traceable knowledge shared by people and AI agents.","frontmatter":{"page_id":"home","layout":"home","title":"Ershu","description":"Self-hosted project context for private enterprise code, turning multiple repositories into searchable, traceable knowledge shared by people and AI agents.","hero":{"name":"Ershu","text":"Give a complex project a memory shared by people and AI","tagline":"Organize private frontend, backend, and service repositories into searchable, traceable project context that can keep pace with the code. Teams read it in the web app while AI agents query the same facts through MCP.","image":{"src":"/favicon.ico","alt":"Ershu mascot"},"actions":[{"theme":"brand","text":"Complete your first analysis","link":"/en/guide/quick-start"},{"theme":"alt","text":"See whether Ershu fits","link":"#who-is-ershu-for"}]},"features":[{"title":"Understand the project across repositories","details":"Place frontend, backend, services, and shared libraries in one project view instead of rebuilding context across repositories."},{"title":"Follow an answer back to source","details":"Documents, search results, and chat citations retain source locations so a conclusion can be checked against current code."},{"title":"Give people and AI the same facts","details":"Team members read through the web app while development agents query the same documents, structure, and retrieval results through MCP."},{"title":"Keep project knowledge aligned with code","details":"Establish a complete project baseline first, then refresh facts, relationships, and search indexes as commits change."}]},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md","lastUpdated":1786289447000}'),o={name:"en/index.md"};function i(n,e,c,d,l,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h2 id="the-hardest-part-rarely-lives-in-one-file" tabindex="-1">The hardest part rarely lives in one file <a class="header-anchor" href="#the-hardest-part-rarely-lives-in-one-file" aria-label="Permalink to &quot;The hardest part rarely lives in one file&quot;">​</a></h2><p>Complex projects hide their difficulty between repositories: which endpoint a page calls, which service an endpoint depends on, and why one setting changes an entire workflow. New contributors search repeatedly, maintainers explain the same boundaries, and development agents rebuild context for every task.</p><div class="home-card-grid home-card-grid--three"><article class="home-card"><p class="home-card-label">Enter an unfamiliar project</p><h3>Find the entry points, boundaries, and critical flows</h3><p>Start with project documents, repository trees, search, and code relationships instead of guessing which repository or maintainer to approach first.</p></article><article class="home-card"><p class="home-card-label">Understand a legacy system</p><h3>Rebuild project knowledge from current code</h3><p>When old documentation is missing or stale, organize structure, explanations, and relationships for the current commit and keep the source available for verification.</p></article><article class="home-card"><p class="home-card-label">Work with coding agents</p><h3>Give an agent project context, not merely a directory</h3><p>Let agents query organized project facts within their permissions, reducing repeated scans and code that is irrelevant to the current task.</p></article></div><aside class="home-statement"><p class="home-statement-label">Reliable context for development agents</p><p class="home-statement-title">Do not push more code into AI. Let it retrieve relevant, version-aware, verifiable project context when it needs it.</p><p>Ershu makes project documents, code search, relationships, and source locations reusable through the web app, API, and MCP. This can reduce repeated reading and irrelevant context. Actual token use depends on the project, task, and model and should be measured on real workloads.</p></aside><h2 id="designed-for-private-enterprise-code" tabindex="-1">Designed for private enterprise code <a class="header-anchor" href="#designed-for-private-enterprise-code" aria-label="Permalink to &quot;Designed for private enterprise code&quot;">​</a></h2><p>The value of self-hosting is not only where a service runs. It is also the ability to decide who can access each project, how code may be read, and which model services are used.</p><div class="home-card-grid home-card-grid--four"><article class="home-card home-card--compact"><p class="home-card-label">Self-hosted</p><h3>Deployment defines the data boundary</h3><p>The operator manages services, repository credentials, and storage on infrastructure it controls.</p></article><article class="home-card home-card--compact"><p class="home-card-label">Read-only analysis</p><h3>Understand code without running repository scripts</h3><p>The Worker extracts project facts with restricted read-only workspace tools and limits paths, file sizes, and tool budgets.</p></article><article class="home-card home-card--compact"><p class="home-card-label">Permission boundaries</p><h3>Authorize members and agents separately</h3><p>Project membership protects the web app, while MCP keys can further restrict projects and tool scopes.</p></article><article class="home-card home-card--compact"><p class="home-card-label">Model choice</p><h3>Configure model channels for your environment</h3><p>Administrators manage LLM, embedding, and reranker channels without putting model secrets in the frontend.</p></article></div><p class="home-note">Self-hosting gives an organization a starting point for controlling its data boundary. Whether code leaves the private network still depends on the model services, network, and logging policy you configure.</p><h2 id="who-is-ershu-for" tabindex="-1">Who is Ershu for? <a class="header-anchor" href="#who-is-ershu-for" aria-label="Permalink to &quot;Who is Ershu for?&quot;">​</a></h2><div class="home-fit-grid"><div class="home-fit-item"><span class="home-fit-index">01</span><div><h3>Products delivered from multiple repositories</h3><p>Frontend, backend, services, shared libraries, and infrastructure are maintained separately but need to be understood as one project.</p></div></div><div class="home-fit-item"><span class="home-fit-index">02</span><div><h3>Unfamiliar or long-lived codebases</h3><p>Reliable documentation is missing, critical knowledge is concentrated in a few people, and the team needs a shared view rebuilt from current source.</p></div></div><div class="home-fit-item"><span class="home-fit-index">03</span><div><h3>Teams bringing AI into development</h3><p>Development agents need permission-aware project context with traceable sources instead of reading every repository from scratch.</p></div></div></div><h2 id="start-with-the-job-in-front-of-you" tabindex="-1">Start with the job in front of you <a class="header-anchor" href="#start-with-the-job-in-front-of-you" aria-label="Permalink to &quot;Start with the job in front of you&quot;">​</a></h2><div class="home-path-grid"><a class="home-path-card" href="/en/overview/what-is-ershu"><span>Decide whether it fits</span><strong>Understand Ershu&#39;s capabilities and boundaries</strong><small>See what it solves and what the current product does not promise.</small></a><a class="home-path-card" href="/en/configuration/"><span>Prepare a self-hosted deployment</span><strong>Configure services, permissions, and trust boundaries</strong><small>Start with basic settings, then configure all five modules.</small></a><a class="home-path-card" href="/en/guide/quick-start"><span>Run a real verification</span><strong>Complete the first full-project analysis</strong><small>Follow observable results from starting the services to generating project knowledge.</small></a><a class="home-path-card" href="/en/development/"><span>Contribute to Ershu</span><strong>Understand its architecture, boundaries, and extensions</strong><small>See how the five modules cooperate and how to add capabilities safely.</small></a></div><section class="home-final-cta"><p class="home-card-label">Start with a real project</p><h2>Ask Ershu a question you are tired of explaining repeatedly</h2><p>Choose a project that genuinely requires cross-repository understanding, establish its complete baseline, and check whether the generated documents, search results, and citations lead back to the right source.</p><div class="home-final-actions"><a class="VPButton medium brand" href="/en/guide/quick-start">Complete the first analysis</a><a class="VPButton medium alt" href="/en/overview/what-is-ershu">Learn more about Ershu</a></div></section><blockquote><p>This site is checked against current source, configuration, types, and tests, then cross-checked with the online Ershu MCP documentation.</p></blockquote>',14)])])}const u=t(o,[["render",i]]);export{m as __pageData,u as default};
